B.Yq=s(["missing"],t.s)
B.edp=new A.d1("q7",B.c4,"","You pierce my soul. I am half agony, half hope.","Jane Austen, Persuasion (1817)",B.Yq)
B.Yl=s(["kind"],t.s)
B.ecP=new A.d1("q8",B.c4,"","There is no charm equal to tenderness of heart.","Jane Austen, Emma (1815)",B.Yl)
B.qI=s(["close"],t.s)
B.edE=new A.d1("q9",B.c4,"","Whatever our souls are made of, his and mine are the same.","Emily Bront\xeb, Wuthering Heights (1847)",B.qI)
B.ecX=new A.d1("q10",B.c4,"","You are part of my existence, part of myself.","Charles Dickens, Great Expectations (1861)",B.qI)
B.ecS=new A.d1("q11",B.c4,"","What greater thing is there for two human souls, than to feel that they are joined for life\u2014to strengthen each other in all labour, to rest on each other in all sorrow, to minister to each other in all pain\u2026","George Eliot, Adam Bede (1859)",B.y_)
B.xZ=s(["space"],t.s)
B.edu=new A.d1("q12",B.c4,"","Love one another, but make not a bond of love:\nLet it rather be a moving sea between the shores of your souls.","Kahlil Gibran, The Prophet (1923)",B.xZ)
B.edi=new A.d1("q13",B.c4,"","And stand together yet not too near together:\nFor the pillars of the temple stand apart,\nAnd the oak tree and the cypress grow not in each other\u2019s shadow.","Kahlil Gibran, The Prophet (1923)",B.xZ)
B.ecM=new A.d1("q14",B.c4,"","Love gives naught but itself and takes naught but from itself.\nLove possesses not nor would it be possessed;\nFor love is sufficient unto love.","Kahlil Gibran, The Prophet (1923)",B.C7)
B.ed7=new A.d1("q15",B.c4,"","Many waters cannot quench love, neither can the floods drown it.","Song of Solomon 8:7, King James Bible (1611)",B.y_)
B.ecQ=new A.d1("q16",B.c4,"","Set me as a seal upon thine heart.","Song of Solomon 8:6, King James Bible (1611)",B.qI)
B.ed4=new A.d1("q17",B.c4,"","O my Luve is like a red, red rose\nThat\u2019s newly sprung in June.","Robert Burns, A Red, Red Rose (1794)",B.C_)
B.ezi=s(["admire","calm"],t.s)
B.edB=new A.d1("q18",B.c4,"","She walks in beauty, like the night\nOf cloudless climes and starry skies.","Lord Byron, She Walks in Beauty (1815)",B.ezi)
B.edn=new A.d1("q19",B.c4,"","The only way to have a friend is to be one.","Ralph Waldo Emerson, Friendship (1841)",B.Yl)
B.edA=new A.d1("q20",B.c4,"","Happy families are all alike; every unhappy family is unhappy in its own way.","Leo Tolstoy, Anna Karenina (1878; tr. Constance Garnett, 1901)",B.ma)
B.ecL=new A.d1("q21",B.c4,"","Love is like a cough \u2014 it cannot be hidden.\n(Mapenzi ni kikohozi, hayafichiki.)","Swahili proverb",B.C_)
B.edm=new A.d1("q22",B.c4,"","Little by little fills the measure.\n(Haba na haba hujaza kibaba.)","Swahili proverb \u2014 small daily kindness builds a love",B.y_)
B.edH=new A.d1("q23",B.c4,"","Where there is a will, there is a way.\n(Penye nia pana njia.)","Swahili proverb",B.ma)
